import re
from robot.api import logger
from ta_egate_cmd_parser.egate_connection import get_connection
from ta_egate_cmd_parser.utils.console_output import format_console_output


class CommandExecutionFailed(Exception):
    """
    Exception class
    """

    def __init__(self, cmd, passreg, failreg, output):
        """

        :param cmd:
        :param passreg:
        :param failreg:
        :param output:
        """
        self.cmd = cmd
        self.passreg = passreg
        self.failreg = failreg
        self.output = output

    def __str__(self):
        self.err = "\ncmd: {}\n pass_regexp: {}\n fail_regexp: {}\n with output: {}" \
            .format(format_console_output(self.cmd, 'info'),
                    self.passreg,
                    self.failreg,
                    format_console_output(self.output, 'error'))
        return self.err


class EgateCommandBase(object):
    """
    Egate command base
    """

    def __init__(self):
        """
        Command base.
        """
        self.executed_phrase = r'^\s*EGATE>.*?EGATE>\s*$'

    def execute(self, egate_id=0, command=None, pass_regexp=None, fail_regexp=None):
        """
        Execute command on connection.

        :param egate_id:
        :param command:
        :param pass_regexp:
        :param fail_regexp:
        :return:
        """
        connection = get_connection(egate_id).connection
        connection.write(command)
        status, output = connection.read_until_regexp(regexp=self.executed_phrase, timeout=5)
        connection.close_connection()
        if pass_regexp:
            status = True if re.search(pass_regexp, output, re.MULTILINE | re.DOTALL) else False
        if fail_regexp:
            status = False if re.search(fail_regexp, output, re.MULTILINE | re.DOTALL) else True
        if not status:
            raise CommandExecutionFailed(command, pass_regexp, fail_regexp, output)
        logger.trace('{} - executed cmd ({}) \nstatus: {}\noutput: {}'.format(self.__class__.__name__, command, status, output))
        return status, output
